package com.proofclean.config;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.Date;
@Component
public class JwtTokenProvider { private final SecretKey key; private final long expirationMs; public JwtTokenProvider(@Value("${proofclean.jwt.secret}") String secret,@Value("${proofclean.jwt.expiration-ms}") long expirationMs){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expirationMs=expirationMs;} public String createToken(String email){Date now=new Date();return Jwts.builder().subject(email).issuedAt(now).expiration(new Date(now.getTime()+expirationMs)).signWith(key).compact();} public String getSubject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} public boolean validate(String token){try{getSubject(token);return true;}catch(JwtException|IllegalArgumentException e){return false;}} }
